WITH fy_ebitda AS (
    SELECT SUM(ebitda) AS total_ebitda
    FROM north.ledger.v_management_headline
    WHERE EXTRACT(YEAR FROM period_end) = 2025
)
SELECT total_ebitda AS answer FROM fy_ebitda;

WITH fy2025 AS (
  SELECT SUM(EbitdaAfterAddbacks) AS total_ebitda
  FROM west.ops.MonthlyPnl
  WHERE EXTRACT(YEAR FROM MonthEnding) = 2025
)
SELECT total_ebitda AS answer FROM fy2025;
